import{_ as a,o as r,c as t,ae as i}from"./chunks/framework.RRduUuAx.js";const d=JSON.parse('{"title":"Exchange Rates","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/05-exchange-rate-guide.md","filePath":"v1/en/guide/05-exchange-rate-guide.md"}'),n={name:"v1/en/guide/05-exchange-rate-guide.md"};function l(o,e,s,c,h,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="exchange-rates" tabindex="-1">Exchange Rates <a class="header-anchor" href="#exchange-rates" aria-label="Permalink to &quot;Exchange Rates&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>Koala supports multi-currency bills with exchange rate lookup and switching.</p><hr><h2 id="💰-what-is-the-base-currency" tabindex="-1">💰 What is the base currency? <a class="header-anchor" href="#💰-what-is-the-base-currency" aria-label="Permalink to &quot;💰 What is the base currency?&quot;">​</a></h2><p>The base currency is the main currency of your ledger. It is used for:</p><ul><li>Displaying amounts across the app</li><li>Calculations in overview and statistics</li><li>Showing exchange rates relative to the base currency</li></ul><hr><h2 id="🚀-change-the-base-currency" tabindex="-1">🚀 Change the base currency <a class="header-anchor" href="#🚀-change-the-base-currency" aria-label="Permalink to &quot;🚀 Change the base currency&quot;">​</a></h2><h3 id="option-1-from-currency-settings" tabindex="-1">Option 1: From Currency Settings <a class="header-anchor" href="#option-1-from-currency-settings" aria-label="Permalink to &quot;Option 1: From Currency Settings&quot;">​</a></h3><ol><li>Open Koala and go to <strong>Settings</strong></li><li>Tap <strong>Currency settings</strong></li><li>Tap <strong>Base currency</strong></li><li>Select a new currency</li></ol><p>Koala will refresh exchange rates and update amount display.</p><h3 id="option-2-from-ledger-details" tabindex="-1">Option 2: From Ledger Details <a class="header-anchor" href="#option-2-from-ledger-details" aria-label="Permalink to &quot;Option 2: From Ledger Details&quot;">​</a></h3><ol><li>Open <strong>Ledger management</strong></li><li>Open the ledger details</li><li>Tap <strong>Ledger currency</strong></li><li>Select a new currency</li></ol><hr><h2 id="📊-exchange-rate-list" tabindex="-1">📊 Exchange rate list <a class="header-anchor" href="#📊-exchange-rate-list" aria-label="Permalink to &quot;📊 Exchange rate list&quot;">​</a></h2><p>You can:</p><ul><li>Browse supported currencies</li><li>See rates relative to the base currency</li><li>Tap the refresh button to fetch the latest rates</li></ul><blockquote><p>💡 Tip:</p><ul><li>Rates are fetched from the server via a third-party exchange-rate provider.</li><li>When offline, Koala uses cached rates.</li></ul></blockquote><hr><h2 id="💱-how-exchange-rates-affect-bills" tabindex="-1">💱 How exchange rates affect bills <a class="header-anchor" href="#💱-how-exchange-rates-affect-bills" aria-label="Permalink to &quot;💱 How exchange rates affect bills&quot;">​</a></h2><ul><li>Koala converts amounts using the <strong>current exchange rate</strong>.</li><li>If the exchange rate changes (for example after refresh), the converted display of historical bills may also change.</li><li>The original transaction amount is not changed.</li></ul><hr><h2 id="🔄-caching" tabindex="-1">🔄 Caching <a class="header-anchor" href="#🔄-caching" aria-label="Permalink to &quot;🔄 Caching&quot;">​</a></h2><p>Koala caches exchange rates to improve performance.</p><ul><li>Cache is updated when you refresh rates or change base currency or ledger currency.</li></ul><hr><p><strong>Last updated</strong>: May 2026</p>',28)])])}const p=a(n,[["render",l]]);export{d as __pageData,p as default};
